package org.eclipse.rdf4j.sail.lmdb;

import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertFalse;
import static org.junit.jupiter.api.Assertions.assertNotEquals;
import static org.junit.jupiter.api.Assertions.assertThrows;
import static org.junit.jupiter.api.Assertions.assertTrue;

import java.lang.management.ManagementFactory;
import java.lang.management.ThreadInfo;
import java.nio.file.Path;
import java.util.concurrent.CountDownLatch;
import java.util.concurrent.FutureTask;
import java.util.concurrent.TimeUnit;
import java.util.concurrent.atomic.AtomicBoolean;

import org.eclipse.rdf4j.common.iteration.QueryExecutionDeadline;
import org.eclipse.rdf4j.query.QueryInterruptedException;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.EnumSource;
import org.junit.jupiter.params.provider.ValueSource;

class ValueStoreWriterReadLifetimeTest {

	enum Terminal {
		COMMIT,
		ROLLBACK,
		CLEAR,
		CLOSE
	}

	@ParameterizedTest
	@EnumSource(Terminal.class)
	void terminalOperationWaitsForBorrowedWriterRead(Terminal terminal, @TempDir Path directory) throws Exception {
		ValueStore values = new ValueStore(directory.toFile(), new LmdbStoreConfig());
		CountDownLatch readEntered = new CountDownLatch(1);
		CountDownLatch releaseRead = new CountDownLatch(1);
		CountDownLatch terminalStarted = new CountDownLatch(1);
		FutureTask<Boolean> read = new FutureTask<>(() -> {
			values.startTransaction(false);
			return values.readTransaction(0L, (stack, transaction) -> {
				assertNotEquals(0L, transaction, "an authorized writer read needs a live native transaction");
				values.readTransaction(0L, (nestedStack, nestedTransaction) -> {
					assertEquals(transaction, nestedTransaction, "nested reads must borrow the same writer");
					return null;
				});
				readEntered.countDown();
				await(releaseRead);
				return true;
			});
		});
		FutureTask<Void> end = new FutureTask<>(() -> {
			terminalStarted.countDown();
			switch (terminal) {
			case COMMIT -> values.commit();
			case ROLLBACK -> values.rollback();
			case CLEAR -> values.clear();
			case CLOSE -> values.close();
			}
			return null;
		});
		Thread reader = new Thread(read, "dictionary-writer-read");
		Thread closer = new Thread(end, "dictionary-writer-terminal");
		reader.start();
		try {
			assertTrue(readEntered.await(5, TimeUnit.SECONDS));
			closer.start();
			assertTrue(terminalStarted.await(5, TimeUnit.SECONDS));
			awaitTerminalBlockedOrCompleted(closer, end);
			assertFalse(end.isDone(), "native writer consumption must wait for its borrowed read: " + terminal);
		} finally {
			releaseRead.countDown();
			reader.join(5_000L);
			closer.join(5_000L);
			values.close();
		}
		assertTrue(read.get(5, TimeUnit.SECONDS));
		end.get(5, TimeUnit.SECONDS);
		assertFalse(reader.isAlive());
		assertFalse(closer.isAlive());
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void expiredDeadlineRejectsOwnerAndNestedWriterReads(boolean nested, @TempDir Path directory) throws Exception {
		ValueStore values = new ValueStore(directory.toFile(), new LmdbStoreConfig());
		try {
			values.startTransaction(false);
			if (nested) {
				values.readTransaction(0L, (stack, transaction) -> {
					assertExpiredReadRejected(values);
					return null;
				});
			} else {
				assertExpiredReadRejected(values);
			}
			values.rollback();
		} finally {
			values.close();
		}
	}

	private static void assertExpiredReadRejected(ValueStore values) {
		CountDownLatch expired = new CountDownLatch(1);
		AtomicBoolean called = new AtomicBoolean();
		try (QueryExecutionDeadline deadline = QueryExecutionDeadline.start(1L);
				QueryExecutionDeadline.Scope ignored = deadline.enter();
				QueryExecutionDeadline.Registration registration = deadline.onExpiration(expired::countDown)) {
			await(expired);
			assertThrows(QueryInterruptedException.class, () -> values.readTransaction(0L, (stack, transaction) -> {
				called.set(true);
				return null;
			}));
			assertFalse(called.get(), "an expired writer read must not enter its native callback");
		}
	}

	private static void awaitTerminalBlockedOrCompleted(Thread thread, FutureTask<?> terminal) {
		long deadline = System.nanoTime() + TimeUnit.SECONDS.toNanos(5);
		while (!terminal.isDone()) {
			ThreadInfo info = ManagementFactory.getThreadMXBean().getThreadInfo(thread.threadId(), Integer.MAX_VALUE);
			if (info != null && (info.getThreadState() == Thread.State.WAITING
					|| info.getThreadState() == Thread.State.BLOCKED)) {
				for (StackTraceElement frame : info.getStackTrace()) {
					if (frame.getClassName().equals(ValueStore.class.getName())) {
						return;
					}
				}
			}
			assertTrue(System.nanoTime() < deadline, "writer terminal operation must block or finish");
			Thread.onSpinWait();
		}
	}

	private static void await(CountDownLatch latch) {
		try {
			assertTrue(latch.await(5, TimeUnit.SECONDS));
		} catch (InterruptedException failure) {
			Thread.currentThread().interrupt();
			throw new AssertionError(failure);
		}
	}
}
